], "occasions": ["casual"], "colors": ["negro", "gris"], "fabric": "denim"}, {"id": "ea1971df-25b6-4e15-b3c1-91fe0a5176fb", "category": "pantalones", "styles": ["urbano", "streetwear"], "niche": ["Gorpcore"], "occasions": ["casual"], "colors": ["negro"], "fabric": "algodón tipo pana"}, {"id": "f90c7ab6-062f-4f53-a8c2-f7cb6f25a7c7", "category": "jeans", "styles": ["urbano", "streetwear"], "niche": [], "occasions": ["casual"], "colors": ["celeste"], "fabric": "denim"}, {"id": "a21b742c-009c-4675-a972-d6f6ffcaf40f", "category": "jeans", "styles": ["urbano"], "niche": [], "occasions": ["casual"], "colors": ["gris", "negro"], "fabric": "denim"}, {"id": "c544cccd-6a05-4476-9fca-f594ca7c19b8", "category": "jeans", "styles": ["urbano", "streetwear"], "niche": [], "occasions": ["casual"], "colors": ["crudo", "estampado"], "fabric": "denim"}, {"id": "80689eab-d622-4631-b252-6ac09dbd4c38", "category": "jeans", "styles": ["urbano", "minimalista"], "niche": [], "occasions": ["dia-a-dia"], "colors": ["negro"], "fabric": "denim"}, {"id": "71864da1-dccf-4607-b9f3-b94b9f2fd89b", "category": "jeans", "styles": ["vintage", "urbano"], "niche": [], "occasions": ["casual"], "colors": ["azul", "verde"], "fabric": "denim"}, {"id": "2f3cbae5-e5b0-4966-b9e6-6d9e03791921", "category": "jeans", "styles": ["vintage", "urbano"], "niche": [], "occasions": ["casual"], "colors": ["beige", "verde-oliva"], "fabric": "denim"}, {"id": "ad483748-cc10-4b9b-bd92-8d1c49ae4481", "category": "accesorios", "styles": ["artesanal", "elegante"], "niche": [], "occasions": ["evento", "noche"], "colors": ["vino", "plateado"], "fabric": "vidrio"}, {"id": "c96a55e0-4a28-4903-979f-b24ba1bfd52b", "category": "accesorios", "styles": ["artesanal", "colorido"], "niche": [], "occasions": ["beachwear", "viaje"], "colors": ["multicolor"], "fabric": "vidrio"}, {"id": "9536174b-2e79-4a68-9444-6e2cf1d238fc", "category": "tops", "styles": ["urbano", "minimalista"], "niche": [], "occasions": ["noche", "fiesta"], "colors": ["negro"], "fabric": "denim"}, {"id": "c5c28309-2eaf-4b29-86a3-14f3e0caacdb", "category": "blusas", "styles": ["minimalista", "urbano"], "niche": [], "occasions": ["brunch", "trabajo"], "colors": ["azul-oscuro"], "fabric": "denim"}, {"id": "a7ac4bbf-ed76-4f72-9e64-6e8418af53b5", "category": "jeans", "styles": ["artesanal", "boho"], "niche": [], "occasions": ["brunch", "viaje"], "colors": ["azul", "multicolor"], "fabric": "denim y crochet"}, {"id": "c7a23dfe-a61e-4144-b8fe-150ca36f2e19", "category": "jeans", "styles": ["urbano", "vintage"], "niche": [], "occasions": ["casual"], "colors": ["verde"], "fabric": "denim"}, {"id": "3db78a6b-b0e9-4c8b-aa91-7804595687c9", "category": "tops", "styles": ["minimalista", "caribeno"], "niche": [], "occasions": ["dia-a-dia", "viaje"], "colors": ["blanco", "rosado", "dorado"], "fabric": null}, {"id": "935a8297-7672-4b42-a408-3d68f2478fb1", "category": "pantalones", "styles": ["urbano", "streetwear"], "niche": [], "occasions": ["noche", "fiesta"], "colors": ["estampado", "cafe"], "fabric": null}, {"id": "e9480d74-5f0e-4908-8eda-14b62c11fc26", "category": "enterizos-y-conjuntos", "styles": ["romantico", "clasico"], "niche": [], "occasions": ["brunch", "evento"], "colors": ["blanco", "amarillo"], "fabric": null}, {"id": "f4488064-2442-43cd-b5fe-7f4ad981491f", "category": "enterizos-y-conjuntos", "styles": ["clasico", "romantico"], "niche": [], "occasions": ["brunch", "viaje"], "colors": ["estampado", "azul"], "fabric": null}, {"id": "ad2285f7-591a-430b-a673-bd69b7c098bc", "category": "enterizos-y-conjuntos", "styles": ["minimalista", "urbano"], "niche": [], "occasions": ["dia-a-dia", "viaje"], "colors": ["azul"], "fabric": "denim"}, {"id": "5ea811b4-db03-47ca-bc7b-e2a161278244", "category": "vestidos", "styles": ["romantico", "colorido"], "niche": [], "occasions": ["fiesta", "brunch"], "colors": ["estampado"], "fabric": null}, {"id": "dbaa07fd-ec9c-4d90-9ae1-78d4b846e817", "category": "vestidos", "styles": ["romantico", "caribeno"], "niche": [], "occasions": ["evento", "fiesta"], "colors": ["rojo"], "fabric": "algodón"}, {"id": "93a420d8-0d37-4131-9e5f-23dbc3b4466e", "category": "vestidos", "styles": ["clasico", "romantico"], "niche": [], "occasions": ["brunch", "evento"], "colors": ["blanco"], "fabric": null}]'::jsonb;
  r jsonb;
  gid uuid;
  nm text;
  cat_id uuid;
  want_styles uuid[];
  want_occ uuid[];
begin
  -- 1. Estilos de nicho propuestos, creados como estilos del equipo.
  for nm in select distinct jsonb_array_elements_text(p->'niche') from jsonb_array_elements(payload) p loop
    if not exists (select 1 from tags where type = 'style'
                   and name_key = regexp_replace(public.f_unaccent(lower(nm)), '[^a-z0-9]', '', 'g')) then
      insert into tags (type, name, slug)
      values ('style', nm, public.vocab_slug(nm, array(select slug from tags where type = 'style')));
    end if;
  end loop;

  for r in select * from jsonb_array_elements(payload) loop
    gid := (r->>'id')::uuid;
    continue when not exists (select 1 from garments where id = gid and status = 'published');

    -- 2. Categoría
    select id into cat_id from tags where type = 'category' and slug = r->>'category';
    if cat_id is not null then
      delete from garment_tags gt using tags t
        where gt.garment_id = gid and t.id = gt.tag_id and t.type = 'category';
      insert into garment_tags (garment_id, tag_id) values (gid, cat_id);
    end if;

    -- 3. Estilos: sugeridos + nicho primero, luego los actuales; máximo 6.
    select array_agg(id order by ord) into want_styles from (
      select distinct on (id) id, ord from (
        select t.id, s.ord from jsonb_array_elements_text(r->'styles') with ordinality s(slug, ord)
          join tags t on t.type = 'style' and t.slug = s.slug
        union all
        select t.id, 100 + s.ord from jsonb_array_elements_text(r->'niche') with ordinality s(nm, ord)
          join tags t on t.type = 'style'
           and t.name_key = regexp_replace(public.f_unaccent(lower(s.nm)), '[^a-z0-9]', '', 'g')
        union all
        select gt.tag_id, 1000 from garment_tags gt join tags t on t.id = gt.tag_id
          where gt.garment_id = gid and t.type = 'style'
      ) x order by id, ord
    ) y;
    delete from garment_tags gt using tags t
      where gt.garment_id = gid and t.id = gt.tag_id and t.type = 'style';
    insert into garment_tags (garment_id, tag_id)
      select gid, u from unnest(want_styles[1:6]) u;

    -- 4. Ocasiones: sugeridas primero, luego las actuales; máximo 3.
    select array_agg(id order by ord) into want_occ from (
      select distinct on (id) id, ord from (
        select t.id, s.ord from jsonb_array_elements_text(r->'occasions') with ordinality s(slug, ord)
          join tags t on t.type = 'occasion' and t.slug = s.slug
        union all
        select gt.tag_id, 1000 from garment_tags gt join tags t on t.id = gt.tag_id
          where gt.garment_id = gid and t.type = 'occasion'
      ) x order by id, ord
    ) y;
    delete from garment_tags gt using tags t
      where gt.garment_id = gid and t.id = gt.tag_id and t.type = 'occasion';
    insert into garment_tags (garment_id, tag_id)
      select gid, u from unnest(want_occ[1:3]) u;

    -- 5. Colores (el trigger reescribe garments.color).
    delete from garment_colors where garment_id = gid;
    insert into garment_colors (garment_id, color_id)
      select gid, c.id from jsonb_array_elements_text(r->'colors') with ordinality s(slug, ord)
        join colors c on c.slug = s.slug
      order by s.ord
      limit 3;

    -- 6. Tela solo si estaba vacía.
    if coalesce(r->>'fabric', '') <> '' then
      update garments set fabric = r->>'fabric' where id = gid and coalesce(fabric, '') = '';
    end if;
  end loop;
end $$;
